// Copy to env.js (gitignored) for local dev. In deployed environments this
// file is regenerated by CI right before upload — see docs/decisions.md
// "Runtime-injected frontend config, not build-time VITE_* vars" — so
// nothing here is ever read outside a local `pnpm dev`/`docker compose`
// run.
window.__ENV__ = {
  // The backend's WS origin. No default: the app throws on startup if
  // this is unset.
  WS_URL: "ws://localhost:8080",

  // The same backend's HTTP origin (REST endpoints — /stats and beyond).
  // No default: the app throws on startup if this is unset.
  API_URL: "http://localhost:8080",

  // From your Clerk application's dashboard (clerk.com) — safe to expose
  // client-side, that's what "publishable" means. Not required when
  // VITE_AUTH_MODE=mock in .env (the default for local dev) — see
  // docs/decisions.md "Local dev auth: mock provider, not a Clerk
  // sandbox".
  CLERK_PUBLISHABLE_KEY: "",

  // Sentry DSN for frontend error reporting (anagrabble#46). Safe to expose
  // client-side — a DSN only permits writing events. Leave empty for local
  // dev: with no DSN, src/observability just logs to the console and never
  // touches the network. CI sets this per environment, along with
  // SENTRY_ENVIRONMENT ("development"/"production") and RELEASE (the commit
  // SHA), neither of which is worth setting locally.
  SENTRY_DSN: "",
};
